  return { ...r, erstelltVonName: nameVon(db, r.erstelltVon), beschreibungKurz: regelText(r, { vorlagen: vorlagenNamen, konten }), letzterLauf: letzte ? { am: letzte.am, status: letzte.status, objektTitel: letzte.objektTitel } : null };
